import clsx from 'clsx';
import { noop } from 'lodash-es';
import React, {
  ElementRef,
  forwardRef,
  useImperativeHandle,
  useRef,
} from 'react';
import { useIntl } from 'react-intl';

import { expressionCSS, hiddenCSS } from './DateTimeInput.sty.js';
import { useDateTimeInput } from './hooks/useDateTimeInput.js';
import type { DateTimeInputProps, DateTimeInputRef } from './types.js';
import { _VisuallyHidden as VisuallyHidden } from '../../core/components/visually-hidden/VisuallyHidden.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { _useFormFieldValidation } from '../forms-core/hooks/useFormFieldValidation.js';
import { _SpinButtonGroup as SpinButtonGroup } from '../spin-buttons/spin-button-group/SpinButtonGroup.js';

function preventDefault(e: React.DragEvent | React.ClipboardEvent) {
  e.preventDefault();
}

/** DateTimeRangePicker component
 * @internal
 */
export const DateTimeInput = forwardRef<DateTimeInputRef, DateTimeInputProps>(
  (props, forwardedRef) => {
    const { formatMessage } = useIntl();

    const rootRef = useRef<ElementRef<'span'>>(null);
    const inputRef = useRef<ElementRef<'input'>>(null);
    const expressionInputRef = useRef<HTMLSpanElement>(null);
    const intl = useIntl();
    const { ariaProps } = _useFormFieldValidation(null);

    const {
      disabled,
      readOnly,
      placeholder = formatMessage({
        defaultMessage: 'Date time',
        id: 'KeejL6AAywDF4I+J',
        description: 'Timestamp',
      }),
      className,
      style,
      name,
      'data-testid': dataTestId,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      'aria-describedby': ariaDescribedBy,
      'aria-details': ariaDetails,
      controlId,
    }: DateTimeInputProps = props;

    const {
      expressionInputHandler,
      expressionOnFocusHandler,
      expressionOnBlurHandler,
      expressionOnKeyDownHandler,
      onCopyCapture,
      onPaste,
      value,
      valueType,
      spinButtons,
      focus,
    } = useDateTimeInput(props, expressionInputRef);

    useImperativeHandle(
      forwardedRef,
      () => ({
        element: rootRef.current,
        inputRef: inputRef.current,
        focus,
      }),
      [focus],
    );

    const expressionLabel = intl.formatMessage({
      defaultMessage: 'Expression',
      id: '7WRZP/iF7skDvWYi',
      description: 'Textbox to enter a dql timeframe expression.',
    });

    return (
      <Flex
        ref={rootRef}
        as="span"
        className={className}
        style={style}
        data-testid={dataTestId}
        onCopyCapture={onCopyCapture}
        onPaste={onPaste}
        gap={0}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledBy}
        aria-describedby={ariaDescribedBy}
        aria-details={ariaDetails}
      >
        <VisuallyHidden>
          <input
            id={controlId}
            ref={inputRef}
            name={name}
            value={value?.value ?? ''}
            onChange={noop}
            disabled={disabled}
            tabIndex={-1}
            onFocus={focus}
            {...ariaProps}
          />
        </VisuallyHidden>
        <span
          className={clsx(
            expressionCSS,
            valueType !== 'expression' ? hiddenCSS : undefined,
          )}
          role="textbox"
          spellCheck={false}
          tabIndex={0}
          style={
            {
              '--data-placeholder': `"${placeholder}"`,
            } as React.CSSProperties
          }
          ref={expressionInputRef}
          contentEditable={!disabled && !readOnly}
          onInput={expressionInputHandler}
          onFocus={expressionOnFocusHandler}
          onBlur={expressionOnBlurHandler}
          onKeyDown={expressionOnKeyDownHandler}
          onPaste={preventDefault}
          onDragOver={preventDefault}
          onDrop={preventDefault}
          aria-label={expressionLabel}
        />
        <SpinButtonGroup
          className={valueType !== 'iso8601' ? hiddenCSS : undefined}
          valueOverflow
        >
          {spinButtons}
        </SpinButtonGroup>
      </Flex>
    );
  },
);
